import{_ as i,o as a,c as n,aj as h}from"./chunks/framework.BdtAaXf2.js";const c=JSON.parse('{"title":"28-创建 struct 实例","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/28-创建 struct 实例/28-创建 struct 实例.md","filePath":"仓颉入门到实战/28-创建 struct 实例/28-创建 struct 实例.md","lastUpdated":1735346856000,"__rawMarkdown":"# 28-创建 struct 实例\\n\\n定义了 `struct` 类型后，即可通过调用 `struct` 的构造函数来创建 `struct` 实例。在 `struct` 定义之外，通过 `struct` 类型\\n\\n名调用构造函数。例如，下例中定义了一个 `Rectangle` 类型的变量 `r`。\\n\\n```javascript\\nlet r = Rectangle(10, 20)\\n```\\n\\n创建了 `struct` 实例之后，可以通过实例访问它的（`public` 修饰的）实例成员变量和实例成员函数。例如，下例中通过 `r.wid`\\n\\n`th` 和 `r.height` 可分别访问 `r` 中 `width` 和 `height` 的值，通过 `r.area()` 可以调用 `r` 的成员函数 `area`。\\n\\n```javascript\\nlet r = Rectangle(10, 20)\\nlet width = r.width   // width = 10\\nlet height = r.height // height = 20\\nlet a = r.area()      // a = 200\\n```\\n\\n如果希望通过 `struct` 实例去修改成员变量的值，需要将 `struct` 类型的变量定义为可变变量，并且被修改的成员变量也必须是\\n\\n可变成员变量（使用 `var` 定义）。举例如下：\\n\\n```javascript\\nstruct Rectangle {\\n    public var width: Int64\\n    public var height: Int64\\n\\n    public init(width: Int64, height: Int64) {\\n        this.width = width\\n        this.height = height\\n    }\\n\\n    public func area() {\\n        width * height\\n    }\\n}\\n\\nmain() {\\n    var r = Rectangle(10, 20) // r.width = 10, r.height = 20\\n    r.width = 8               // r.width = 8\\n    r.height = 24             // r.height = 24\\n    let a = r.area()          // a = 192\\n}\\n```\\n\\n在赋值或传参时，会对 `struct` 实例进行复制，生成新的实例，**对其中一个实例的修改并不会影响另外一个实例**。以赋值为\\n\\n例，下面的例子中，将 `r1` 赋值给 `r2` 之后，修改 `r1` 的 `width` 和 `height` 的值，并不会影响 `r2` 的 `width` 和 `height` 值。\\n\\n```javascript\\nstruct Rectangle {\\n    public var width: Int64\\n    public var height: Int64\\n\\n    public init(width: Int64, height: Int64) {\\n        this.width = width\\n        this.height = height\\n    }\\n\\n    public func area() {\\n        width * height\\n    }\\n}\\n\\nmain() {\\n    var r1 = Rectangle(10, 20) // r1.width = 10, r1.height = 20\\n    var r2 = r1                // r2.width = 10, r2.height = 20\\n    r1.width = 8               // r1.width = 8\\n    r1.height = 24             // r1.height = 24\\n    let a1 = r1.area()         // a1 = 192\\n    let a2 = r2.area()         // a2 = 200\\n}\\n```"}'),t={name:"仓颉入门到实战/28-创建 struct 实例/28-创建 struct 实例.md"};function l(p,s,e,k,r,d){return a(),n("div",null,[...s[0]||(s[0]=[h("",13)])])}const g=i(t,[["render",l]]);export{c as __pageData,g as default};
